VALUES
  ('g2-s7-age-easy-0001', 2, 7, 'age_problems', 'easy', '{"mult": 2, "years": 10}'::jsonb, 'In 10 years, Alex will be 2 times Alex''s current age. How old is Alex now?', '["10", "5", "12", "8"]'::jsonb, '10', '["divided the years by the multiplier itself instead of by (multiplier − 1) — forgets that the given years only cover the EXTRA part of the growth, not the whole multiple", "added the multiplier to the years instead of using it as a multiplier — treats the relationship like an additive comparison, not a multiplicative one", "subtracted the multiplier from the years instead of solving the proportional relationship"]'::jsonb, 'Let Alex''s age now be a. In 10 years, Alex will be a + 10, and that equals 2 × a. So a + 10 = 2a, which means 10 = a × (2 − 1), so a = 10 ÷ 1 = 10.', NULL, '', 15, NULL, 'template-mtap-g2-s7-age-v1', true),
