  ('g2-s7-age-easy-0008', 2, 7, 'age_problems', 'easy', '{"mult": 3, "years": 18}'::jsonb, 'In 18 years, Ella will be 3 times Ella''s current age. How old is Ella now?', '["6", "15", "21", "9"]'::jsonb, '9', '["divided the years by the multiplier itself instead of by (multiplier − 1) — forgets that the given years only cover the EXTRA part of the growth, not the whole multiple", "added the multiplier to the years instead of using it as a multiplier — treats the relationship like an additive comparison, not a multiplicative one", "subtracted the multiplier from the years instead of solving the proportional relationship"]'::jsonb, 'Let Ella''s age now be a. In 18 years, Ella will be a + 18, and that equals 3 × a. So a + 18 = 3a, which means 18 = a × (3 − 1), so a = 18 ÷ 2 = 9.', NULL, '', 15, NULL, 'template-mtap-g2-s7-age-v1', true),
  ('g2-s7-age-avg-0001', 2, 7, 'age_problems', 'average', '{"age": 7, "mult": 3}'::jsonb, 'Marco is 7 years old now. In how many years will Marco be 3 times as old as Marco is right now?', '["21", "10", "4", "14"]'::jsonb, '14', '["multiplied the current age by the multiplier itself instead of by (multiplier − 1) — double-counts the starting age as part of the growth", "added the multiplier to the current age instead of finding how many years are needed to reach that multiple", "subtracted the multiplier from the current age instead of solving for the number of years"]'::jsonb, 'Marco is 7 now. In y years, Marco will be 7 + y, and that should equal 3 × 7. So y = 7 × (3 − 1) = 14 years.', NULL, 'Builds on the Easy tier''s age/years/multiplier relationship, run in the opposite direction: given the current age, solve for the missing number of years instead of the missing age.', 30, NULL, 'template-mtap-g2-s7-age-v1', true),
  ('g2-s7-age-avg-0002', 2, 7, 'age_problems', 'average', '{"age": 10, "mult": 4}'::jsonb, 'Tala is 10 years old now. In how many years will Tala be 4 times as old as Tala is right now?', '["6", "30", "14", "40"]'::jsonb, '30', '["multiplied the current age by the multiplier itself instead of by (multiplier − 1) — double-counts the starting age as part of the growth", "added the multiplier to the current age instead of finding how many years are needed to reach that multiple", "subtracted the multiplier from the current age instead of solving for the number of years"]'::jsonb, 'Tala is 10 now. In y years, Tala will be 10 + y, and that should equal 4 × 10. So y = 10 × (4 − 1) = 30 years.', NULL, 'Builds on the Easy tier''s age/years/multiplier relationship, run in the opposite direction: given the current age, solve for the missing number of years instead of the missing age.', 30, NULL, 'template-mtap-g2-s7-age-v1', true),
  ('g2-s7-age-avg-0003', 2, 7, 'age_problems', 'average', '{"age": 8, "mult": 2}'::jsonb, 'Ravi is 8 years old now. In how many years will Ravi be 2 times as old as Ravi is right now?', '["8", "10", "16", "6"]'::jsonb, '8', '["multiplied the current age by the multiplier itself instead of by (multiplier − 1) — double-counts the starting age as part of the growth", "added the multiplier to the current age instead of finding how many years are needed to reach that multiple", "subtracted the multiplier from the current age instead of solving for the number of years"]'::jsonb, 'Ravi is 8 now. In y years, Ravi will be 8 + y, and that should equal 2 × 8. So y = 8 × (2 − 1) = 8 years.', NULL, 'Builds on the Easy tier''s age/years/multiplier relationship, run in the opposite direction: given the current age, solve for the missing number of years instead of the missing age.', 30, NULL, 'template-mtap-g2-s7-age-v1', true),
